[
  {
    "statement": "For primates, identified alternatives to processed or commercial pellet diets include presenting whole foods rather than chopped or processed items.",
    "citations": [
      "1323"
    ]
  },
  {
    "statement": "Presenting whole foods to macaques increased the amount of food the macaques consumed and the time they spent feeding.",
    "citations": [
      "1323"
    ]
  },
  {
    "statement": "Offering fresh produce to primates instead of pellet feed is an alternative diet.",
    "citations": [
      "1335"
    ]
  },
  {
    "statement": "Offering fresh produce to rhesus macaques increased the macaques' feeding time and reduced their inactivity.",
    "citations": [
      "1335"
    ]
  },
  {
    "statement": "Providing cut branches, also known as browse, is an alternative feeding method for primates.",
    "citations": [
      "1332"
    ]
  },
  {
    "statement": "Captive gorillas used wild-like processing skills when given stinging nettles.",
    "citations": [
      "1332"
    ]
  },
  {
    "statement": "Providing nectar, including artificial nectar, is an alternative food source for primates.",
